            section_Xc(:,2) = geometry_Xc(:,2) + 0.45_rk*sin(geometry_pi*xi)*[0.0_rk,1.0_rk,1.0_rk,0.0_rk]
            section_Xc(:,3) = 3.0_rk*xi + 0.15_rk*xi*geometry_Xc(:,1)
            call curve_sections(section)%set(&
