            expected = [1.0_rk, 0.5_rk, -0.25_rk, 0.25_rk, 0.1875_rk, -0.375_rk, 0.125_rk],&
            tol      = 1.0e-14_rk,&
            msg      = "arbitrary-order chain-rule coefficients are incorrect",&
            group    = "forcad_multipatch")
