        call mp_bad_geom%connect(id1, "right", id2, "right", 0)

        call mp_bad_continuity%add_patch(c1, id1)
        call mp_bad_continuity%add_patch(c2, id2)
        call mp_bad_continuity%connect(id1, "right", id2, "left", 2)

        call ut%test(ti)%check(&
