        integer, intent(inout) :: ti

        type(nurbs_surface) :: s1
        type(nurbs_surface) :: s2
        type(nurbs_multipatch_surface) :: mp_discontinuous
        integer, allocatable :: map(:)
        integer :: id1, id2

