        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

