        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call ut%test(ti)%check(&
            name     = "rotate_Xc(Y-axis): geometry preserved (NURBS)",&
            res      = nurbs%get_Xc(),&
            expected = Xc,&
            tol      = nurbs_curve_tol,&
