        call bsp%export_iges("iges/test_bsp_surface.iges")

        call ut%test(ti)%check(&
            name     = "NURBS modified-control geometry recreation",&
            res      = nurbs%get_Xg(),&
            expected = Xg,&
            tol      = 1e-5_rk,&
            msg      = "Modified-control geometry recreation is incorrect.",&
            group    = "forcad_nurbs_surface")
