        Xc(2,:) = [5.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [0.0_rk, 5.0_rk, 0.0_rk]
        Xc(4,:) = [5.0_rk, 5.0_rk, 0.0_rk]

        allocate(Wc(size(Xc, 1)))
        Wc = 1.0_rk
        Wc(2) = 0.9_rk

        knot1 = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        knot2 = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]

