        call nurbs%basis(res1=20, res2=20, Tgc=Tgc)
        call bsp%basis(res1=20, res2=20, Tgc=Tgc)

        call nurbs%basis(Xt=[0.0_rk, 0.0_rk], Tgc=Tgc1)
