        call nurbs%derivative(Xt=[0.0_rk,0.0_rk], dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=[0.0_rk,0.0_rk], dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=[0.0_rk,0.0_rk], dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
