        call bsp%export_Xth("vtk/test_bsp_surface_Xth.vtk")

        call nurbs%export_iges("iges/test_nurbs_surface.iges")
        call bsp%export_iges("iges/test_bsp_surface.iges")

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis([1,1])
