        call bsp%set([2,2], Xc)

        call nurbs%create(Xt1 = nurbs%get_Xt(1), Xt2 = nurbs%get_Xt(2))
        call bsp%create(Xt1 = bsp%get_Xt(1), Xt2 = bsp%get_Xt(2))

        call nurbs%export_Xc("vtk/test_nurbs_surface_Xc.vtk")
