            d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(&
            Xt1=[(real(i-1, rk) / real(20-1, rk), i=1, 20)], Xt2=[(real(i-1, rk) / real(20-1, rk), i=1, 20)],&
