        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

