        call bsp%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])

        call nurbs%translate_Xg([5.0_rk, 5.0_rk, 5.0_rk])
        call nurbs%translate_Xg([-5.0_rk, -5.0_rk, -5.0_rk])

        call bsp%translate_Xg([5.0_rk, 5.0_rk, 5.0_rk])
        call bsp%translate_Xg([-5.0_rk, -5.0_rk, -5.0_rk])

