        call nurbs%insert_knots(2, [0.25_rk, 0.75_rk], [1,1])

        call bsp%insert_knots(1, [0.25_rk, 0.75_rk], [1,1])
        call bsp%insert_knots(2, [0.25_rk, 0.75_rk], [1,1])

