        call bsp%export_Xc("vtk/test_bsp_surface_Xc.vtk")

        call nurbs%export_Xg("vtk/test_nurbs_surface_Xg.vtk")
        call bsp%export_Xg("vtk/test_bsp_surface_Xg.vtk")

