            [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk], Xproj)
        call sproj%nearest_point2([0.2_rk, 0.3_rk, 0.4_rk], 1.0e-12_rk, 0, Xt_out, Xg_out)

        call ut%test(ti)%check(&
            name     = "zero-iteration surface projection outputs",&
