        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)

        elemConn = nurbs%cmp_elem_Xg_vis([1,1,1])
