        call bsp%export_Xg("vtk/test_bsp_volume_Xg.vtk")

        call nurbs%export_Xth("vtk/test_nurbs_volume_Xth.vtk")
        call bsp%export_Xth("vtk/test_bsp_volume_Xth.vtk")

        call nurbs%basis(res1=20, res2=20, res3=20, Tgc=Tgc)
