        call nurbs%basis(Xt=[0.25_rk, 0.5_rk, 0.75_rk], Tgc=Tgc1)
        call bsp%basis(Xt=[0.25_rk, 0.5_rk, 0.75_rk], Tgc=Tgc1b)
