        real(rk), allocatable :: Tgc1e(:), Tgc1be(:)
        real(rk) :: knot1(4), knot2(4), knot3(4), volume, volumeb
        real(rk) :: nearest_Xg(3), nearest_Xt(3)
        integer :: id

        allocate(Xc(8, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
