        call bsp%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc())

        call nurbs%create(20, 20, 20)
        call bsp%create(20, 20, 20)

        call nurbs%export_Xc("vtk/test_nurbs_volume_Xc.vtk")
