        call bsp%export_Xth("vtk/test_bsp_volume_Xth.vtk")

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis([1,1,1])
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
