        Xc(2,:) = [5.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [0.0_rk, 5.0_rk, 0.0_rk]
        Xc(4,:) = [5.0_rk, 5.0_rk, 0.0_rk]
