        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis([1,1,1])
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)

        elemConn = nurbs%cmp_elem()
