        call bsp%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call nurbs%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])

        call bsp%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call bsp%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])

        call ut%test(ti)%check(&
            name     = "NURBS control-net translation round trip",&
