        call bsp%elevate_degree(1, 2)
        call bsp%elevate_degree(2, 2)
        call bsp%elevate_degree(3, 2)

        call nurbs%create()
        call bsp%create()

        call nurbs%export_Xc("vtk/test_nurbs_volume_Xc.vtk")
        call bsp%export_Xc("vtk/test_bsp_volume_Xc.vtk")

