        call nurbs%set_C([0.0_rk, 0.0_rk, 0.0_rk], 1.0_rk, 2.0_rk, 2.0_rk)

        call nurbs%set_hexahedron([2.0_rk, 3.0_rk, 4.0_rk], [2,2,2])
        call nurbs%create(2, 2, 2)
        elemConn = nurbs%cmp_elem()
