                do ii = 1, 4
                    idx = ((kk - 1)*4 + jj - 1)*4 + ii
                    Xc_nonopen(idx,:) = [real(ii - 1, rk), real(jj - 1, rk), real(kk - 1, rk)]
                end do
            end do
        end do
        knot_nonopen = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

