        call volume_ref%create(Xt1=Xt_ref, Xt2=Xt_ref, Xt3=Xt_ref)
        Xg_ref = volume_ref%get_Xg()

        call volume_ref%insert_knots(1, [2.5_rk], [1])
        call volume_ref%insert_knots(2, [3.0_rk], [1])
        call volume_ref%insert_knots(3, [3.5_rk], [1])
