        call volume_ref%remove_knots(2, [3.0_rk], [1])
        call volume_ref%remove_knots(3, [3.5_rk], [1])
        call volume_ref%create(Xt1=Xt_ref, Xt2=Xt_ref, Xt3=Xt_ref)

        call volume_ref%elevate_degree(1, 1)
