        A4 = reshape([4.0_rk, 1.0_rk, 1.0_rk, 3.0_rk], [2,2])
        R_expected = reshape([1.0_rk/11.0_rk, 7.0_rk/11.0_rk], [2,1])
        R = solve(A4, reshape([1.0_rk, 2.0_rk], [2,1]))

        p = 2
        rr = 1
        s  = 0
        k  = 2
        allocate(knot_in(0:5))
