        Pw(1,:) = [0.5_rk, 0.5_rk]
        Pw(2,:) = [1.0_rk, 1.0_rk]

        call insert_knot_A_5_1(p, knot_in, Pw, 0.5_rk, k, s, rr, nq, knot_out, Qw)

        deallocate(knot_in, knot_out, Pw, Qw)
