        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        call ut%test(ti)%check(&
