        real(rk) :: B_ref(4), dB_ref(4), d2B_ref(4)
        real(rk) :: u(2), v(2), w(4)
        real(rk), allocatable :: u2(:), v2(:), w2(:)
        real(rk) :: A2x2(2,2), Bk(4,2)
        real(rk), allocatable :: A(:), vec(:), M(:,:)
        real(rk), allocatable :: X1(:), X2(:), X3(:)
