        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

