        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

        conn1D = elemConn_C0(5, 2)

        call elemConn_Cn(5, 2, [0.0_rk, 0.5_rk, 1.0_rk], [3,1,3], conn1D)

        conn2D = elemConn_C0(5, 5, 2, 2)

        call elemConn_Cn(5, 5, 2, 2, [0.0_rk, 0.5_rk, 1.0_rk], [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], conn2D)

        conn3D = elemConn_C0(5, 5, 5, 2, 2, 2)

        call elemConn_Cn(5, 5, 5, 2, 2, 2, &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], [3,1,3], conn3D)

        allocate(A2(3,3))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, &
            0.0_rk, 1.0_rk, 4.0_rk, &
            5.0_rk, 6.0_rk, 0.0_rk], [3,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(3,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk], [3,2])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(2,3))
        A2 = reshape([1.0_rk, 4.0_rk, 2.0_rk, 5.0_rk, 3.0_rk, 6.0_rk], [2,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        call ut%test(ti)%check(&
            name     = "active_knot_bounds_nonopen",&
            res      = [knot_start(knot, nc, degree), knot_end(knot, nc, degree)],&
            expected = [2.0_rk, 4.0_rk],&
            msg      = "Active parameter domain should use knot(p+1):knot(nc+1)",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0061


    subroutine forcad_utils_0062(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: utils_vtk_file = "vtk/test_output.vtk"
        real(rk) :: Xt
        integer  :: nc, degree
        real(rk) :: knot(7)
        real(rk) :: B4(4)
        real(rk) :: dB(4)
        real(rk) :: d2B(4)
        real(rk) :: A4(2,2)
        real(rk) :: B_ref(4), dB_ref(4), d2B_ref(4)
        real(rk) :: u(2), v(2), w(4)
        real(rk), allocatable :: u2(:), v2(:), w2(:)
        real(rk) :: A2x2(2,2), Bk(4,2)
        real(rk), allocatable :: A(:), vec(:), M(:,:)
        real(rk), allocatable :: X1(:), X2(:), X3(:)
        real(rk), allocatable :: Xt2(:,:), Xt3(:,:)
        real(rk), allocatable :: R(:,:), R_expected(:,:)
        real(rk), allocatable :: knot_in(:), knot_out(:), Pw(:,:), Qw(:,:)
        real(rk), allocatable :: Xksi(:,:), Wksi(:)
        real(rk), allocatable :: K3(:), K2(:), K1(:), out(:)
        integer, allocatable :: conn1D(:,:)
        integer, allocatable :: conn2D(:,:)
        integer, allocatable :: conn3D(:,:)
        integer :: nq, p, rr, s, k
        real(rk), allocatable :: A2(:,:), A_inv(:,:)

        degree = 2
        nc     = 4
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 0.5_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        Xt     = 0.5_rk

        B4 = basis_bspline(Xt, knot, nc, degree)
        B_ref = [0.0_rk, 0.5_rk, 0.5_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB, B4)
        dB_ref  = [0.0_rk, -2.0_rk, 2.0_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB, B4)
        d2B_ref = [0.0_rk, 4.0_rk, -12.0_rk, 8.0_rk]

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B)

        Xt = -0.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        Xt = 1.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        X1 = [1.0_rk, 2.0_rk]
        X2 = [10.0_rk, 20.0_rk]
        X3 = [100.0_rk]

        call ndgrid(X1, X2, Xt2)
        call ndgrid(X1, X2, X3, Xt3)

        A = [1.0_rk, 2.0_rk]
        vec = [3.0_rk, 4.0_rk, 5.0_rk]
        M = dyad(A, vec)

        u = [1.0_rk, 2.0_rk]
        v = [3.0_rk, 4.0_rk]
        w = kron(u, v)

        A2x2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk], [2,2])
        Bk   = kron(u, A2x2)

        A4 = reshape([4.0_rk, 1.0_rk, 1.0_rk, 3.0_rk], [2,2])
        R_expected = reshape([1.0_rk/11.0_rk, 7.0_rk/11.0_rk], [2,1])
        R = solve(A4, reshape([1.0_rk, 2.0_rk], [2,1]))

        p = 2
        rr = 1
        s  = 0
        k  = 2
        allocate(knot_in(0:5))
        knot_in = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(0:2,1:2))
        Pw(0,:) = [0.0_rk, 0.0_rk]
        Pw(1,:) = [0.5_rk, 0.5_rk]
        Pw(2,:) = [1.0_rk, 1.0_rk]

        call insert_knot_A_5_1(p, knot_in, Pw, 0.5_rk, k, s, rr, nq, knot_out, Qw)

        deallocate(knot_in, knot_out, Pw, Qw)
        knot_in = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(1:2,1:2))
        Pw(1,:) = [0.0_rk, 0.0_rk]
        Pw(2,:) = [0.5_rk, 0.5_rk]
        call elevate_degree_A_5_9(t=1, knot=knot_in, degree=1, Xcw=Pw, nc_new=nc, knot_new=knot_out, Xcw_new=Qw)

        call gauss_leg([0.0_rk, 1.0_rk], 2, Xksi=vec, Wksi=A)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [2, 2], Xksi=Xksi, Wksi=Wksi)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [1, 1, 1], Xksi=Xksi, Wksi=Wksi)

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="binary")

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="ascii")

        K1 = [1.0_rk, 2.0_rk]
        K2 = [3.0_rk]
        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

        conn1D = elemConn_C0(5, 2)

        call elemConn_Cn(5, 2, [0.0_rk, 0.5_rk, 1.0_rk], [3,1,3], conn1D)

        conn2D = elemConn_C0(5, 5, 2, 2)

        call elemConn_Cn(5, 5, 2, 2, [0.0_rk, 0.5_rk, 1.0_rk], [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], conn2D)

        conn3D = elemConn_C0(5, 5, 5, 2, 2, 2)

        call elemConn_Cn(5, 5, 5, 2, 2, 2, &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], [3,1,3], conn3D)

        allocate(A2(3,3))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, &
            0.0_rk, 1.0_rk, 4.0_rk, &
            5.0_rk, 6.0_rk, 0.0_rk], [3,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(3,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk], [3,2])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(2,3))
        A2 = reshape([1.0_rk, 4.0_rk, 2.0_rk, 5.0_rk, 3.0_rk, 6.0_rk], [2,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        B4 = basis_bspline(2.5_rk, knot, nc, degree)

        call ut%test(ti)%check(&
            name     = "basis_nonopen_sum",&
            res      = sum(B4),&
            expected = 1.0_rk,&
            msg      = "Unclamped basis should partition unity inside active domain",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0062


    subroutine forcad_utils_0063(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: utils_vtk_file = "vtk/test_output.vtk"
        real(rk) :: Xt
        integer  :: nc, degree
        real(rk) :: knot(7)
        real(rk) :: B4(4)
        real(rk) :: dB(4)
        real(rk) :: d2B(4)
        real(rk) :: A4(2,2)
        real(rk) :: B_ref(4), dB_ref(4), d2B_ref(4)
        real(rk) :: u(2), v(2), w(4)
        real(rk), allocatable :: u2(:), v2(:), w2(:)
        real(rk) :: A2x2(2,2), Bk(4,2)
        real(rk), allocatable :: A(:), vec(:), M(:,:)
        real(rk), allocatable :: X1(:), X2(:), X3(:)
        real(rk), allocatable :: Xt2(:,:), Xt3(:,:)
        real(rk), allocatable :: R(:,:), R_expected(:,:)
        real(rk), allocatable :: knot_in(:), knot_out(:), Pw(:,:), Qw(:,:)
        real(rk), allocatable :: Xksi(:,:), Wksi(:)
        real(rk), allocatable :: K3(:), K2(:), K1(:), out(:)
        integer, allocatable :: conn1D(:,:)
        integer, allocatable :: conn2D(:,:)
        integer, allocatable :: conn3D(:,:)
        integer :: nq, p, rr, s, k
        real(rk), allocatable :: A2(:,:), A_inv(:,:)

        degree = 2
        nc     = 4
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 0.5_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        Xt     = 0.5_rk

        B4 = basis_bspline(Xt, knot, nc, degree)
        B_ref = [0.0_rk, 0.5_rk, 0.5_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB, B4)
        dB_ref  = [0.0_rk, -2.0_rk, 2.0_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB, B4)
        d2B_ref = [0.0_rk, 4.0_rk, -12.0_rk, 8.0_rk]

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B)

        Xt = -0.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        Xt = 1.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        X1 = [1.0_rk, 2.0_rk]
        X2 = [10.0_rk, 20.0_rk]
        X3 = [100.0_rk]

        call ndgrid(X1, X2, Xt2)
        call ndgrid(X1, X2, X3, Xt3)

        A = [1.0_rk, 2.0_rk]
        vec = [3.0_rk, 4.0_rk, 5.0_rk]
        M = dyad(A, vec)

        u = [1.0_rk, 2.0_rk]
        v = [3.0_rk, 4.0_rk]
        w = kron(u, v)

        A2x2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk], [2,2])
        Bk   = kron(u, A2x2)

        A4 = reshape([4.0_rk, 1.0_rk, 1.0_rk, 3.0_rk], [2,2])
        R_expected = reshape([1.0_rk/11.0_rk, 7.0_rk/11.0_rk], [2,1])
        R = solve(A4, reshape([1.0_rk, 2.0_rk], [2,1]))

        p = 2
        rr = 1
        s  = 0
        k  = 2
        allocate(knot_in(0:5))
        knot_in = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(0:2,1:2))
        Pw(0,:) = [0.0_rk, 0.0_rk]
        Pw(1,:) = [0.5_rk, 0.5_rk]
        Pw(2,:) = [1.0_rk, 1.0_rk]

        call insert_knot_A_5_1(p, knot_in, Pw, 0.5_rk, k, s, rr, nq, knot_out, Qw)

        deallocate(knot_in, knot_out, Pw, Qw)
        knot_in = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(1:2,1:2))
        Pw(1,:) = [0.0_rk, 0.0_rk]
        Pw(2,:) = [0.5_rk, 0.5_rk]
        call elevate_degree_A_5_9(t=1, knot=knot_in, degree=1, Xcw=Pw, nc_new=nc, knot_new=knot_out, Xcw_new=Qw)

        call gauss_leg([0.0_rk, 1.0_rk], 2, Xksi=vec, Wksi=A)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [2, 2], Xksi=Xksi, Wksi=Wksi)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [1, 1, 1], Xksi=Xksi, Wksi=Wksi)

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="binary")

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="ascii")

        K1 = [1.0_rk, 2.0_rk]
        K2 = [3.0_rk]
        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

        conn1D = elemConn_C0(5, 2)

        call elemConn_Cn(5, 2, [0.0_rk, 0.5_rk, 1.0_rk], [3,1,3], conn1D)

        conn2D = elemConn_C0(5, 5, 2, 2)

        call elemConn_Cn(5, 5, 2, 2, [0.0_rk, 0.5_rk, 1.0_rk], [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], conn2D)

        conn3D = elemConn_C0(5, 5, 5, 2, 2, 2)

        call elemConn_Cn(5, 5, 5, 2, 2, 2, &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], [3,1,3], conn3D)

        allocate(A2(3,3))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, &
            0.0_rk, 1.0_rk, 4.0_rk, &
            5.0_rk, 6.0_rk, 0.0_rk], [3,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(3,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk], [3,2])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(2,3))
        A2 = reshape([1.0_rk, 4.0_rk, 2.0_rk, 5.0_rk, 3.0_rk, 6.0_rk], [2,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        B4 = basis_bspline(2.5_rk, knot, nc, degree)

        B4 = basis_bspline(1.5_rk, knot, nc, degree)

        call ut%test(ti)%check(&
            name     = "basis_nonopen_inactive_span",&
            res      = sum(B4),&
            expected = 0.0_rk,&
            msg      = "Unclamped basis should be zero outside active domain",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0063


    subroutine forcad_utils_0064(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: utils_vtk_file = "vtk/test_output.vtk"
        real(rk) :: Xt
        integer  :: nc, degree
        real(rk) :: knot(7)
        real(rk) :: B4(4)
        real(rk) :: dB(4)
        real(rk) :: d2B(4)
        real(rk) :: A4(2,2)
        real(rk) :: B_ref(4), dB_ref(4), d2B_ref(4)
        real(rk) :: u(2), v(2), w(4)
        real(rk), allocatable :: u2(:), v2(:), w2(:)
        real(rk) :: A2x2(2,2), Bk(4,2)
        real(rk), allocatable :: A(:), vec(:), M(:,:)
        real(rk), allocatable :: X1(:), X2(:), X3(:)
        real(rk), allocatable :: Xt2(:,:), Xt3(:,:)
        real(rk), allocatable :: R(:,:), R_expected(:,:)
        real(rk), allocatable :: knot_in(:), knot_out(:), Pw(:,:), Qw(:,:)
        real(rk), allocatable :: Xksi(:,:), Wksi(:)
        real(rk), allocatable :: K3(:), K2(:), K1(:), out(:)
        integer, allocatable :: conn1D(:,:)
        integer, allocatable :: conn2D(:,:)
        integer, allocatable :: conn3D(:,:)
        integer :: nq, p, rr, s, k
        real(rk), allocatable :: A2(:,:), A_inv(:,:)

        degree = 2
        nc     = 4
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 0.5_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        Xt     = 0.5_rk

        B4 = basis_bspline(Xt, knot, nc, degree)
        B_ref = [0.0_rk, 0.5_rk, 0.5_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB, B4)
        dB_ref  = [0.0_rk, -2.0_rk, 2.0_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB, B4)
        d2B_ref = [0.0_rk, 4.0_rk, -12.0_rk, 8.0_rk]

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B)

        Xt = -0.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        Xt = 1.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        X1 = [1.0_rk, 2.0_rk]
        X2 = [10.0_rk, 20.0_rk]
        X3 = [100.0_rk]

        call ndgrid(X1, X2, Xt2)
        call ndgrid(X1, X2, X3, Xt3)

        A = [1.0_rk, 2.0_rk]
        vec = [3.0_rk, 4.0_rk, 5.0_rk]
        M = dyad(A, vec)

        u = [1.0_rk, 2.0_rk]
        v = [3.0_rk, 4.0_rk]
        w = kron(u, v)

        A2x2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk], [2,2])
        Bk   = kron(u, A2x2)

        A4 = reshape([4.0_rk, 1.0_rk, 1.0_rk, 3.0_rk], [2,2])
        R_expected = reshape([1.0_rk/11.0_rk, 7.0_rk/11.0_rk], [2,1])
        R = solve(A4, reshape([1.0_rk, 2.0_rk], [2,1]))

        p = 2
        rr = 1
        s  = 0
        k  = 2
        allocate(knot_in(0:5))
        knot_in = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(0:2,1:2))
        Pw(0,:) = [0.0_rk, 0.0_rk]
        Pw(1,:) = [0.5_rk, 0.5_rk]
        Pw(2,:) = [1.0_rk, 1.0_rk]

        call insert_knot_A_5_1(p, knot_in, Pw, 0.5_rk, k, s, rr, nq, knot_out, Qw)

        deallocate(knot_in, knot_out, Pw, Qw)
        knot_in = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(1:2,1:2))
        Pw(1,:) = [0.0_rk, 0.0_rk]
        Pw(2,:) = [0.5_rk, 0.5_rk]
        call elevate_degree_A_5_9(t=1, knot=knot_in, degree=1, Xcw=Pw, nc_new=nc, knot_new=knot_out, Xcw_new=Qw)

        call gauss_leg([0.0_rk, 1.0_rk], 2, Xksi=vec, Wksi=A)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [2, 2], Xksi=Xksi, Wksi=Wksi)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [1, 1, 1], Xksi=Xksi, Wksi=Wksi)

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="binary")

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="ascii")

        K1 = [1.0_rk, 2.0_rk]
        K2 = [3.0_rk]
        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

        conn1D = elemConn_C0(5, 2)

        call elemConn_Cn(5, 2, [0.0_rk, 0.5_rk, 1.0_rk], [3,1,3], conn1D)

        conn2D = elemConn_C0(5, 5, 2, 2)

        call elemConn_Cn(5, 5, 2, 2, [0.0_rk, 0.5_rk, 1.0_rk], [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], conn2D)

        conn3D = elemConn_C0(5, 5, 5, 2, 2, 2)

        call elemConn_Cn(5, 5, 5, 2, 2, 2, &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], [3,1,3], conn3D)

        allocate(A2(3,3))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, &
            0.0_rk, 1.0_rk, 4.0_rk, &
            5.0_rk, 6.0_rk, 0.0_rk], [3,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(3,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk], [3,2])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(2,3))
        A2 = reshape([1.0_rk, 4.0_rk, 2.0_rk, 5.0_rk, 3.0_rk, 6.0_rk], [2,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        B4 = basis_bspline(2.5_rk, knot, nc, degree)

        B4 = basis_bspline(1.5_rk, knot, nc, degree)

        call ut%test(ti)%check(&
            name     = "compute_multiplicity_large_scaled",&
            res      = compute_multiplicity([1.0e6_rk, 1.0e6_rk + 8.0_rk*epsilon(1.0_rk)*1.0e6_rk, 2.0e6_rk, 2.0e6_rk]),&
            expected = [1, 1, 2],&
            msg      = "Distinct representable knots must remain topologically distinct",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0064


    subroutine forcad_utils_0065(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: utils_vtk_file = "vtk/test_output.vtk"
        real(rk) :: Xt
        integer  :: nc, degree
        real(rk) :: knot(7)
        real(rk) :: B4(4)
        real(rk) :: dB(4)
        real(rk) :: d2B(4)
        real(rk) :: A4(2,2)
        real(rk) :: B_ref(4), dB_ref(4), d2B_ref(4)
        real(rk) :: u(2), v(2), w(4)
        real(rk), allocatable :: u2(:), v2(:), w2(:)
        real(rk) :: A2x2(2,2), Bk(4,2)
        real(rk), allocatable :: A(:), vec(:), M(:,:)
        real(rk), allocatable :: X1(:), X2(:), X3(:)
        real(rk), allocatable :: Xt2(:,:), Xt3(:,:)
        real(rk), allocatable :: R(:,:), R_expected(:,:)
        real(rk), allocatable :: knot_in(:), knot_out(:), Pw(:,:), Qw(:,:)
        real(rk), allocatable :: Xksi(:,:), Wksi(:)
        real(rk), allocatable :: K3(:), K2(:), K1(:), out(:)
        integer, allocatable :: conn1D(:,:)
        integer, allocatable :: conn2D(:,:)
        integer, allocatable :: conn3D(:,:)
        integer :: nq, p, rr, s, k
        real(rk), allocatable :: A2(:,:), A_inv(:,:)

        degree = 2
        nc     = 4
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 0.5_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        Xt     = 0.5_rk

        B4 = basis_bspline(Xt, knot, nc, degree)
        B_ref = [0.0_rk, 0.5_rk, 0.5_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB, B4)
        dB_ref  = [0.0_rk, -2.0_rk, 2.0_rk, 0.0_rk]

        call basis_bspline_der(Xt, knot, nc, degree, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB, B4)
        d2B_ref = [0.0_rk, 4.0_rk, -12.0_rk, 8.0_rk]

        call basis_bspline_2der(Xt, knot, nc, degree, d2B, dB)

        call basis_bspline_2der(Xt, knot, nc, degree, d2B)

        Xt = -0.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        Xt = 1.1_rk
        B4 = basis_bspline(Xt, knot, nc, degree)

        X1 = [1.0_rk, 2.0_rk]
        X2 = [10.0_rk, 20.0_rk]
        X3 = [100.0_rk]

        call ndgrid(X1, X2, Xt2)
        call ndgrid(X1, X2, X3, Xt3)

        A = [1.0_rk, 2.0_rk]
        vec = [3.0_rk, 4.0_rk, 5.0_rk]
        M = dyad(A, vec)

        u = [1.0_rk, 2.0_rk]
        v = [3.0_rk, 4.0_rk]
        w = kron(u, v)

        A2x2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk], [2,2])
        Bk   = kron(u, A2x2)

        A4 = reshape([4.0_rk, 1.0_rk, 1.0_rk, 3.0_rk], [2,2])
        R_expected = reshape([1.0_rk/11.0_rk, 7.0_rk/11.0_rk], [2,1])
        R = solve(A4, reshape([1.0_rk, 2.0_rk], [2,1]))

        p = 2
        rr = 1
        s  = 0
        k  = 2
        allocate(knot_in(0:5))
        knot_in = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(0:2,1:2))
        Pw(0,:) = [0.0_rk, 0.0_rk]
        Pw(1,:) = [0.5_rk, 0.5_rk]
        Pw(2,:) = [1.0_rk, 1.0_rk]

        call insert_knot_A_5_1(p, knot_in, Pw, 0.5_rk, k, s, rr, nq, knot_out, Qw)

        deallocate(knot_in, knot_out, Pw, Qw)
        knot_in = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        allocate(Pw(1:2,1:2))
        Pw(1,:) = [0.0_rk, 0.0_rk]
        Pw(2,:) = [0.5_rk, 0.5_rk]
        call elevate_degree_A_5_9(t=1, knot=knot_in, degree=1, Xcw=Pw, nc_new=nc, knot_new=knot_out, Xcw_new=Qw)

        call gauss_leg([0.0_rk, 1.0_rk], 2, Xksi=vec, Wksi=A)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [2, 2], Xksi=Xksi, Wksi=Wksi)

        call gauss_leg([0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [0.0_rk, 1.0_rk], [1, 1, 1], Xksi=Xksi, Wksi=Wksi)

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="binary")

        call export_vtk_legacy(filename=utils_vtk_file, points=reshape([0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 0.0_rk, 0.0_rk], [2,3]), &
            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="ascii")

        K1 = [1.0_rk, 2.0_rk]
        K2 = [3.0_rk]
        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

        conn1D = elemConn_C0(5, 2)

        call elemConn_Cn(5, 2, [0.0_rk, 0.5_rk, 1.0_rk], [3,1,3], conn1D)

        conn2D = elemConn_C0(5, 5, 2, 2)

        call elemConn_Cn(5, 5, 2, 2, [0.0_rk, 0.5_rk, 1.0_rk], [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], conn2D)

        conn3D = elemConn_C0(5, 5, 5, 2, 2, 2)

        call elemConn_Cn(5, 5, 5, 2, 2, 2, &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [0.0_rk, 0.5_rk, 1.0_rk], &
            [3,1,3], [3,1,3], [3,1,3], conn3D)

        allocate(A2(3,3))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, &
            0.0_rk, 1.0_rk, 4.0_rk, &
            5.0_rk, 6.0_rk, 0.0_rk], [3,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(3,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk], [3,2])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(2,3))
        A2 = reshape([1.0_rk, 4.0_rk, 2.0_rk, 5.0_rk, 3.0_rk, 6.0_rk], [2,3])
        A_inv = inv(A2)

        deallocate(A2, A_inv)
        allocate(A2(4,4))
        A2 = eye(4)
        A_inv = inv(A2)

        if (allocated(A2)) deallocate(A2)
        allocate(A2(2,2))
        A2 = reshape([1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk],[2,2])
        R = kron_eye(A2, 2)

        u2 = [-1.0_rk, 0.0_rk, 2.0_rk]
        v2 = [ 5.0_rk, -3.0_rk]
        w2 = kron(u2, v2)

        u2 = [-1.0_rk, 2.0_rk]
        v2 = [0.0_rk, 3.0_rk]
        K3 = [-2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]
        out = kron(u2, v2, K3)
        w2  = kron(v2, K3)
        A   = kron(u2, w2)

        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

        degree = 2
        nc = 4
        knot = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        B4 = basis_bspline(2.5_rk, knot, nc, degree)

        B4 = basis_bspline(1.5_rk, knot, nc, degree)

        call ut%test(ti)%check(&
            name     = "compute_multiplicity_value_large_scaled",&
            res      = compute_multiplicity([1.0e6_rk, 1.0e6_rk + 8.0_rk*epsilon(1.0_rk)*1.0e6_rk, 2.0e6_rk, 2.0e6_rk], 1.0e6_rk),&
            expected = 1,&
            msg      = "Multiplicity at a value must use exact knot topology",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0065


    subroutine forcad_utils_0066(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: utils_vtk_file = "vtk/test_output.vtk"
