        Pw(2,:) = [0.5_rk, 0.5_rk]
        call elevate_degree_A_5_9(t=1, knot=knot_in, degree=1, Xcw=Pw, nc_new=nc, knot_new=knot_out, Xcw_new=Qw)

        call gauss_leg([0.0_rk, 1.0_rk], 2, Xksi=vec, Wksi=A)

