        u2 = [2.0_rk, -1.0_rk]
        v2 = [7.0_rk]
        K3 = [1.0_rk, 0.0_rk, -2.0_rk]
        out = kron(u2, v2, K3)

        u2 = [1.0_rk, 2.0_rk]
        v2 = [3.0_rk, 4.0_rk]
        K3 = [5.0_rk]

