            elemConn=reshape([1,2], [1,2]), vtkCellType=3, encoding="ascii")

        K1 = [1.0_rk, 2.0_rk]
        K2 = [3.0_rk]
        K3 = [4.0_rk, 5.0_rk]
        out = kron(K1, K2, K3)

