            reshape([4.0_rk, 5.0_rk, 6.0_rk, 7.0_rk, 8.0_rk, 9.0_rk], [3, 2]), R)

        call sparse_left_matmul(reshape([1.0_rk, 2.0_rk], [1, 2]), reshape([1.0_rk], [1, 1]), R)

        if (allocated(knot_in)) deallocate(knot_in)
