            family_knot = knot_family(:,family)

            family_active = active_knots(family_knot, 6, 2)
            family_multiplicity = active_knot_multiplicity(family_knot, 6, 2)

            family_parameter = 0.5_rk*(family_active(1) + family_active(2))
