    subroutine forcad_utils_0148(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk) :: identity_knot(0:3), identity_controls(2,2)
        real(rk), allocatable :: refined_knot(:), refined_controls(:,:), refinement_map(:,:)
        integer :: last_control

        identity_knot = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        identity_controls = reshape([0.0_rk, 1.0_rk, 0.0_rk, 2.0_rk], [2,2])
        call insert_knot_A_5_1(&
            p  = 1,&
            UP = identity_knot,&
            Pw = identity_controls,&
            u  = 0.5_rk,&
            k  = 1,&
            s  = 0,&
            r  = 0,&
            nq = last_control,&
            UQ = refined_knot,&
            Qw = refined_controls,&
            T  = refinement_map)

        call ut%test(ti)%check(&
            name     = "zero knot insertion identity",&
            res      = last_control == 1 .and. maxval(abs(refined_knot-identity_knot)) <= tiny(1.0_rk) .and. &
                maxval(abs(refined_controls-identity_controls)) <= tiny(1.0_rk) .and. maxval(abs(refinement_map-eye(2))) <= &
                tiny(1.0_rk),&
            expected = .true.,&
            msg      = "Zero knot insertion identity is incorrect.",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0148


    subroutine forcad_utils_0149(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk) :: identity_knot(0:3), identity_controls(2,2)
        real(rk), allocatable :: refined_knot(:), refined_controls(:,:), refinement_map(:,:)
        integer :: last_control, elevated_nc
        logical :: success

        identity_knot = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        identity_controls = reshape([0.0_rk, 1.0_rk, 0.0_rk, 2.0_rk], [2,2])
        call insert_knot_A_5_1(&
            p  = 1,&
            UP = identity_knot,&
            Pw = identity_controls,&
            u  = 0.5_rk,&
            k  = 1,&
            s  = 0,&
            r  = 0,&
            nq = last_control,&
            UQ = refined_knot,&
            Qw = refined_controls,&
            T  = refinement_map)

        call elevate_degree_A_5_9(&
            t        = 0,&
            knot     = identity_knot,&
            degree   = 1,&
            Xcw      = identity_controls,&
            nc_new   = elevated_nc,&
            knot_new = refined_knot,&
            Xcw_new  = refined_controls,&
            Tmap     = refinement_map,&
            success  = success)

        call ut%test(ti)%check(&
            name     = "zero degree elevation identity",&
            res      = success .and. elevated_nc == 2 .and. maxval(abs(refined_knot-identity_knot)) <= tiny(1.0_rk) .and. &
                maxval(abs(refined_controls-identity_controls)) <= tiny(1.0_rk) .and. maxval(abs(refinement_map-eye(2))) <= &
                tiny(1.0_rk),&
            expected = .true.,&
            msg      = "Zero degree elevation identity is incorrect.",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0149


    subroutine forcad_utils_0150(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk) :: identity_knot(0:3), identity_controls(2,2)
        real(rk), allocatable :: refined_knot(:), refined_controls(:,:), refinement_map(:,:)
        integer :: last_control, elevated_nc
        logical :: success

        identity_knot = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk]
        identity_controls = reshape([0.0_rk, 1.0_rk, 0.0_rk, 2.0_rk], [2,2])
        call insert_knot_A_5_1(&
            p  = 1,&
            UP = identity_knot,&
            Pw = identity_controls,&
            u  = 0.5_rk,&
            k  = 1,&
            s  = 0,&
            r  = 0,&
            nq = last_control,&
            UQ = refined_knot,&
            Qw = refined_controls,&
            T  = refinement_map)

        call elevate_degree_A_5_9(&
            t        = 0,&
            knot     = identity_knot,&
            degree   = 1,&
            Xcw      = identity_controls,&
            nc_new   = elevated_nc,&
            knot_new = refined_knot,&
            Xcw_new  = refined_controls,&
            Tmap     = refinement_map,&
            success  = success)

        call elevate_degree_A_5_9(&
            t        = -1,&
            knot     = identity_knot,&
            degree   = 1,&
            Xcw      = identity_controls,&
            nc_new   = elevated_nc,&
            knot_new = refined_knot,&
            Xcw_new  = refined_controls,&
            Tmap     = refinement_map,&
            success  = success)

        call ut%test(ti)%check(&
            name     = "negative degree elevation diagnostic",&
            res      = .not. success .and. elevated_nc == 0 .and. size(refined_knot) == 0 .and. size(refined_controls,1) == 0 &
                .and. size(refinement_map) == 0,&
            expected = .true.,&
            msg      = "Negative degree elevation must return defined empty outputs.",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0150


    subroutine forcad_utils_0151(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: vtk_file = "vtk/test_binary_endian.vtk"
        character(len=*), parameter :: points_marker = "POINTS 2 double"//new_line("a")
        character(len=*), parameter :: cells_marker = "CELLS 1 3"//new_line("a")
        character(len=*), parameter :: types_marker = "CELL_TYPES 1"//new_line("a")
        character(len=*), parameter :: field_marker = "LOOKUP_TABLE default"//new_line("a")
        integer, parameter :: expected_points(48) = [&
            63, 240, 0, 0, 0, 0, 0, 0,&
            64,   0, 0, 0, 0, 0, 0, 0,&
            64,   8, 0, 0, 0, 0, 0, 0,&
            64,  16, 0, 0, 0, 0, 0, 0,&
            64,  20, 0, 0, 0, 0, 0, 0,&
            64,  24, 0, 0, 0, 0, 0, 0]
        integer, parameter :: expected_cells(12) = [&
            0, 0, 0, 2,&
            0, 0, 0, 0,&
            0, 0, 0, 1]
        integer, parameter :: expected_type(4) = [0, 0, 0, 3]
        integer, parameter :: expected_field(16) = [&
            64, 28, 0, 0, 0, 0, 0, 0,&
            64, 32, 0, 0, 0, 0, 0, 0]
        character(len=:), allocatable :: file_contents
        character(len=11) :: field_names(1)
        real(rk) :: points(2,3), point_data(2,1)
        integer :: cells_position, field_position, file_size, file_unit, i, points_position, types_position
        integer :: elem_conn(1,2)
        logical :: exists, valid

        points(1,1) = 1.0_rk
        points(1,2) = 2.0_rk
        points(1,3) = 3.0_rk
        points(2,1) = 4.0_rk
        points(2,2) = 5.0_rk
        points(2,3) = 6.0_rk
        elem_conn(1,1) = 1
        elem_conn(1,2) = 2
        point_data(1,1) = 7.0_rk
        point_data(2,1) = 8.0_rk
        field_names(1) = "temperature"

        call export_vtk_legacy(&
            filename    = vtk_file,&
            points      = points,&
            elemConn    = elem_conn,&
            vtkCellType = 3,&
            point_data  = point_data,&
            field_names = field_names,&
            encoding    = "BINARY")

        file_size = 0
        inquire(&
            file  = vtk_file,&
            exist = exists,&
            size  = file_size)
        valid = exists .and. file_size > 0
        if (valid) then
            allocate(character(len=file_size) :: file_contents)
            open(&
                newunit = file_unit,&
                file    = vtk_file,&
                access  = "stream",&
                form    = "unformatted",&
                action  = "read",&
                status  = "old")
            read(file_unit) file_contents
            close(file_unit)

            points_position = index(file_contents, points_marker)
            cells_position = index(file_contents, cells_marker)
            types_position = index(file_contents, types_marker)
            field_position = index(file_contents, field_marker)
            valid = points_position > 0 .and. cells_position > 0 .and. types_position > 0 .and. field_position > 0
            if (valid) then
                points_position = points_position + len(points_marker)
                cells_position = cells_position + len(cells_marker)
                types_position = types_position + len(types_marker)
                field_position = field_position + len(field_marker)
                valid = points_position + size(expected_points) - 1 <= len(file_contents) .and. &
                    cells_position + size(expected_cells) - 1 <= len(file_contents) .and. &
                    types_position + size(expected_type) - 1 <= len(file_contents) .and. &
                    field_position + size(expected_field) - 1 <= len(file_contents)
            end if
            if (valid) then
                do i = 1, size(expected_points)
                    valid = valid .and. iachar(file_contents(points_position+i-1:points_position+i-1)) == expected_points(i)
                end do
                do i = 1, size(expected_cells)
                    valid = valid .and. iachar(file_contents(cells_position+i-1:cells_position+i-1)) == expected_cells(i)
                end do
                do i = 1, size(expected_type)
                    valid = valid .and. iachar(file_contents(types_position+i-1:types_position+i-1)) == expected_type(i)
                end do
                do i = 1, size(expected_field)
                    valid = valid .and. iachar(file_contents(field_position+i-1:field_position+i-1)) == expected_field(i)
                end do
            end if
        end if

        call ut%test(ti)%check(&
            name     = "binary VTK big-endian representation",&
            res      = valid,&
            expected = .true.,&
            msg      = "Binary VTK big-endian representation is incorrect.",&
            group    = "forcad_utils")
        ti = ti + 1

    end subroutine forcad_utils_0151

